/* Design-only prototype. No audio, account, network or native service calls. */
const app = document.getElementById('app');
const params = new URLSearchParams(location.search);
if (params.has('clean')) document.body.classList.add('clean');
const icons = {
 compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',
 chart:'<path d="M5 19V12M12 19V5M19 19V9"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',
 library:'<path d="M4 4v16M9 4v16M14 5l5-1 3 15-5 1Z"/>',disc:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="M6 10a6 6 0 0 1 4-4"/>',
 queue:'<path d="M4 5h16M4 11h11M4 17h7m5-3 5 3-5 3Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
 settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',
 play:'<path d="m9 5 10 7-10 7Z" fill="currentColor" stroke="none"/>',pause:'<path d="M8 5v14M16 5v14" stroke-width="4"/>',
 next:'<path d="m5 5 10 7-10 7Z" fill="currentColor" stroke="none"/><path d="M19 5v14"/>',prev:'<path d="m19 5-10 7 10 7Z" fill="currentColor" stroke="none"/><path d="M5 5v14"/>',
 heart:'<path d="M20.8 4.8a5.5 5.5 0 0 0-7.8 0L12 6l-1-1.2a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.4a5.5 5.5 0 0 0 0-7.8Z"/>',
 arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',shuffle:'<path d="M3 5h3l12 14h3m-4-4 4 4-4 3M3 19h3l4-5m4-4 4-5h3m-4-3 4 3-4 4"/>',
 repeat:'<path d="m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3"/>',
 volume:'<path d="M4 9h4l5-5v16l-5-5H4Zm13-1a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
 airplay:'<path d="M4 17H2V3h20v14h-2M12 13l7 8H5Z"/>',alert:'<path d="m12 3 10 18H2ZM12 9v5m0 3v.2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
 refresh:'<path d="M21 4v6h-6M3 20v-6h6M5 7a8 8 0 0 1 14-1l2 4M3 14l2 4a8 8 0 0 0 14-1"/>',music:'<path d="M9 18V5l12-2v13M9 8l12-2"/><ellipse cx="5.5" cy="18" rx="3.5" ry="2.5"/><ellipse cx="17.5" cy="16" rx="3.5" ry="2.5"/>'
};
const ic = n => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n] || icons.music}</svg>`;
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art = (i,cls='')=>`<img class="${cls}" src="assets/cover-${i%6}.svg" alt="" draggable="false">`;
const key = s=>`<span class="key ${s.length>1?'wide':''}">${s}</span>`;
const hint = (k,t,primary=false)=>`<span class="hint ${primary?'primary':''}">${key(k)} ${t}</span>`;
const titles={discover:'发现音乐',player:'正在播放',collection:'歌单详情',search:'搜索',library:'我的音乐',charts:'排行榜',queue:'播放队列',account:'我的账号',settings:'设置'};
const playlists=[['海岸线的慢时光','电子 · 氛围 · 放松',0],['微醺爵士，夜色正好','爵士 · 复古 · 夜晚',1],['把心事交给森林','自然 · 轻音乐',2],['下一站，另一个世界','游戏 · 原声 · 探索',3],['日落之前，再走一程','独立 · 公路 · 日落',4],['夜深时的钢琴独白','钢琴 · 安静 · 睡前',5],['留一点时间给自己','精选 · 纯音乐',0],['小小冒险，大大世界','游戏 · 器乐',3]];
const songs=[['晚风经过海岸','CloudTune Sessions','Slow Tides','04:32',0],['留在蓝色时刻','CloudTune Sessions','Slow Tides','03:48',0],['日落的另一边','Westbound','Golden Hour','05:06',4],['林间来信','Field Notes','Into the Green','04:17',2],['没有终点的散步','CloudTune Sessions','Slow Tides','03:56',0],['午夜电台','Room 21','After Hours','04:08',1]];
let scene=params.get('scene')||'discover', state=params.get('state')||'normal', paused=false, reduced=false, volume=70, position=98, currentSong=0, query='晚风', activeTab=0, liked=false, modal=null, toastTimer, origin='discover';
let selectedCollection=0, focusId='', remembered={}, lastContentFocus={}, history=[], modalStack=[];
const btn=(id,action,content,cls='',group='content',extra='')=>`<button class="focusable ${cls}" data-id="${id}" data-action="${action}" data-group="${group}" ${extra}>${content}</button>`;
function sidebar(){return `<aside class="sidebar"><div class="brand"><img src="../../../resources/icon/cloudtune.svg" alt=""><div><b>CloudTune</b><em>NX · MUSIC PLAYER</em></div></div><div class="nav-section">探索音乐</div>${[['discover','compass'],['charts','chart'],['search','search']].map(([p,i])=>nav(p,i)).join('')}<div class="nav-section">音乐资料库</div>${[['library','library'],['player','disc'],['queue','queue']].map(([p,i])=>nav(p,i)).join('')}<div class="sidebar-bottom">${nav('settings','settings')}${btn('nav-account','goto:account',`<span class="avatar">CT</span><span>我的账号</span>`,'profile','nav')}</div></aside>`}
function nav(p,i){return btn('nav-'+p,'goto:'+p,ic(i)+titles[p],`nav-item ${scene===p?'active':''}`,'nav',scene===p?'aria-current="page"':'')}
function output(){return `<div class="output"><span class="badge ${state==='airplay'?'green':''}">${state==='airplay'?ic('airplay'):'<i class="tagdot"></i>'}${state==='airplay'?'AirPlay 1':'BGM · 后台服务'}</span><small>音量 ${volume}%</small></div>`}
function playbackControls(full=false){return `<div class="bar-controls">${btn('previous','previous',ic('prev'),'icon-btn','playback','aria-label="上一首"')}${btn('play','pause',ic(paused?'play':'pause'),'icon-btn play','playback',`aria-label="${paused?'播放':'暂停'}"`)}${btn('next','next',ic('next'),'icon-btn','playback','aria-label="下一首"')}</div><div class="progress-info"><div class="times"><span>${fmt(position)}</span><span>${songs[currentSong][3]}</span></div><div class="progress-track"><div class="progress-fill" style="width:${position/272*100}%"></div></div></div>`}
function fmt(n){return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}
function mini(){let s=songs[currentSong];return `<div class="playerbar">${btn('mini-cover','goto:player',art(s[4],'mini-art'),'','playback','aria-label="打开正在播放"')}<div class="trackinfo"><strong>${s[0]}</strong><small>${s[1]}</small></div>${btn('like','like',ic('heart'),'icon-btn','playback',`aria-label="喜欢歌曲" aria-pressed="${liked}" style="${liked?'color:#ff7e89':''}"`)}${playbackControls()}${output()}${btn('open-queue','goto:queue',ic('queue'),'icon-btn','playback','aria-label="播放队列"')}</div>`}
function footer(full=false){return `<div class="hintbar ${full?'playerfoot':''}"><div class="hintgroup">${full?hint('B','返回'):hint('A',scene==='collection'||scene==='queue'?'播放':'选择',true)}${full?(state==='airplay'?'<span>AirPlay · 发送设备控制曲目</span>':hint('← →','快退 / 快进 10 秒')):hint('B',scene==='collection'?'返回':'导航')}${hint('X',full?'播放选项':'更多')}${hint('Y',paused?'播放':'暂停')}</div><div class="hintgroup">${state==='airplay'?'':hint('L / R','切歌')}${hint('ZL / ZR','音量')}${full?hint('+','返回浏览'):hint('+','正在播放')}</div></div>`}
function head(title,subtitle,meta=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="top-meta">${meta}</div></div>`}
function card(p,i,chart=false){return btn('card-'+i,'collection:'+i,`<div class="art">${chart?`<img src="assets/chart-${i}.svg" alt="">`:art(p[2])}<span class="art-tag">${chart?'CHART':'PLAYLIST'}</span><span class="cover-play">${ic('play')}</span></div><div class="card-copy"><strong>${p[0]}</strong><small>${p[1]}</small></div>`,'music-card')}
function discover(){return head('让音乐，陪你去远方。','在掌心，听见热爱。',`${ic('disc')} 为你发现`)+`<div class="feature"><img class="feature-art" src="assets/cover-0.svg" alt=""><div class="feature-copy"><span class="eyebrow">YOUR DAILY MIX</span><h2>今天，从一首好歌开始</h2><p>每日推荐，为此刻找到合适的旋律。</p>${btn('daily','daily',ic('play')+'开启每日推荐','pill light')}</div></div><div class="sectionhead"><h2>值得慢慢听</h2><div class="quicklinks">${btn('fm','fm','私人 FM','more')}${btn('albums','albums','新碟上架','more')}${btn('browse-more','more','发现更多 '+ic('arrow'),'more')}</div></div><div class="grid">${playlists.slice(0,4).map((p,i)=>card(p,i)).join('')}</div>`}
function tracks(list=songs,limit=6){return `<div class="tracklist">${list.slice(0,limit).map(s=>{let i=songs.indexOf(s);return btn('track-'+i,'track:'+i,`<span class="num">${i===currentSong&&!paused?'<span class="equalizer"><i></i><i></i><i></i></span>':String(i+1).padStart(2,'0')}</span>${art(s[4])}<span class="titlecell"><strong>${s[0]}</strong><small>${s[1]}</small></span><span class="albumcell">${s[2]}</span><span class="duration">${s[3]}</span>`,`trackrow ${i===currentSong?'playing':''}`)}).join('')}</div>`}
function collection(){let p=playlists[selectedCollection%8];return `<div class="backline">${ic('back')} ${history.at(-1)?titles[history.at(-1)]: '发现音乐'}<span> / 歌单</span></div><div class="collection-header">${art(p[2],'collection-cover')}<div><div class="eyebrow">CURATED PLAYLIST</div><h1>${p[0]}</h1><p>CloudTune 精选　·　${songs.length} 首歌曲</p><div class="collection-actions">${btn('play-all','track:0',ic('play')+'播放全部','pill primary')}${btn('subscribe','subscribe',ic('heart')+'收藏歌单','pill')}${btn('collection-more','more',ic('more'),'pill','content','aria-label="歌单选项"')}</div></div></div><div class="tablehead"><span>#</span><span>歌曲 / 歌手</span><span>专辑</span><span>时长</span></div>${tracks(songs,5)}`}
function search(){let filtered=songs.filter(s=>s.join(' ').toLowerCase().includes(query.toLowerCase()));return head('搜索','找到你想听的声音。')+`<label class="searchbox focusable" data-id="search-input" data-group="content" data-action="search-input" tabindex="0">${ic('search')}<input id="search-query" name="query" autocomplete="off" value="${esc(query)}" aria-label="搜索歌曲、歌手、专辑" placeholder="歌曲、歌手、专辑">${key('A')}</label><div class="tabs">${['单曲','歌单','专辑','歌手','歌词'].map((t,i)=>btn('tab-'+i,'tab:'+i,t,i===activeTab?'selected':'')).join('')}</div><p class="results-label">${activeTab===0?`${filtered.length} 首单曲`:'分类展示示例'} · 按 X 更改搜索类型</p>${activeTab===0?(filtered.length?tracks(filtered):'<div class="empty-state" style="height:200px"><h2>没有找到相关音乐</h2><p>试试歌名、歌手名，或更短的关键词。</p></div>'):`<div class="grid">${playlists.slice(0,4).map((p,i)=>card(p,i)).join('')}</div>`}`}
function library(){return head('我的音乐','把喜欢的声音，留在身边。')+`<div class="tabs">${['我的歌单','我喜欢的音乐','收藏专辑','订阅电台','音乐云盘'].map((t,i)=>btn('tab-'+i,'tab:'+i,t,i===activeTab?'selected':'')).join('')}</div>${activeTab===1||activeTab===4?tracks():`<div class="grid compact-grid">${playlists.map((p,i)=>card(p,i)).join('')}</div>`}`}
function charts(){return head('排行榜','发现此刻，正在被听见的声音。')+`<div class="sectionhead"><h2>官方榜单</h2><span class="muted" style="font-size:14px">榜单更新信息以服务返回为准</span></div><div class="grid chart-grid">${[['飙升榜','热度上升的好声音'],['新歌榜','新鲜旋律，抢先收藏'],['热歌榜','每一首，都值得循环'],['原创榜','听见独立表达']].map((p,i)=>card(p,i,true)).join('')}</div>`}
function queue(){return head('播放队列',`${songs.length} 首歌曲 · 顺序播放`,btn('queue-options','more',ic('more')+' 播放选项','pill'))+`<div class="queue-banner">${art(songs[currentSong][4])}<div class="queue-copy"><small>正在播放</small><strong>${songs[currentSong][0]}</strong></div><span class="badge red">${paused?'已暂停':'播放中'}</span>${btn('queue-player','goto:player','打开播放器 '+ic('arrow'),'pill')}</div>${tracks(songs,5)}`}
function account(){return head('音乐，从你的账号开始。','扫码登录，带上熟悉的歌单与收藏。')+`<div class="account-panel"><div><div class="qr"><img src="assets/qr-demo.svg" alt="不可用于登录的设计占位图"></div><p class="muted" style="font-size:12px;text-align:center;margin-top:14px">等待使用网易云音乐 App 扫码</p></div><div class="account-copy"><div class="eyebrow">YOUR MUSIC, EVERYWHERE</div><h2 style="margin-top:14px">在手机上轻轻一扫</h2><p>打开网易云音乐 App 的扫一扫，<br>扫描左侧二维码，并在手机上确认。</p>${btn('qr-refresh','qr-refresh',ic('refresh')+'刷新二维码','pill primary')}<br>${btn('account-manage','account-manage',ic('user')+'管理已有账号','pill')}<p class="account-note">也可以先探索音乐，稍后再登录。</p></div></div>`}
const settingRows=[['账号管理','添加、切换或从本机移除账号','未登录','account-manage'],['播放音质','实际音质取决于账号与曲目权益','极高 · 320 kbps','quality'],['网络代理','HTTP / SOCKS5','直连','proxy'],['AirPlay 1 接收','让同一局域网的设备投送音乐','已开启 · 等待连接','airplay-options'],['播放控制','停止当前音频','停止播放','stop'],['退出应用','后台服务保持运行','退出','exit']];
function settings(){return head('设置','让聆听，顺手一点。')+`<div class="settings-list">${settingRows.map((s,i)=>btn('setting-'+i,s[3],`<span class="setting-title">${s[0]}<small>${s[1]}</small></span><span class="setting-value">${s[2]}${ic('arrow')}</span>`,`setting-row ${i===4?'danger':''}`)).join('')}</div>`}
function player(){let s=songs[currentSong],air=state==='airplay';return `<div class="immersive ${paused?'paused':''}"><div class="playerhead"><div class="source"><img src="../../../resources/icon/cloudtune.svg" alt="CloudTune"><div>${air?'来自 AirPlay 1':'正在播放 · 海岸线的慢时光'}<small>CLOUDTUNE NX / NOW PLAYING</small></div></div>${btn('player-close','back',hint('B','返回音乐'),'pill','player')}</div><div class="record-stage"><div class="record"><div class="label">${air?'<div class="airplay-label">'+ic('airplay')+'<span>AIRPLAY</span></div>':art(s[4])}</div></div><div class="tonearm"><div class="arm-pivot"></div><div class="arm-shaft"></div></div><div class="record-caption"><span>33⅓ RPM</span><span>STEREO / SIDE A</span></div></div><div class="playercopy"><div class="eyebrow">${air?'WIRELESS LISTENING':'IN THE MOMENT'}</div><h1>${air?'来自你的设备':s[0]}</h1><p class="artist">${air?'AirPlay 1 · 正在接收音频':s[1]}</p><div class="album-meta"><span>${air?'同一局域网':s[2]}</span><span>·</span><span>${air?'设备元信息不可用':'CloudTune 原创示例'}</span></div>${air?'':`<div class="lyrics"><p>把喧嚣留在城市那边</p><p class="current">晚风轻轻经过海岸</p><p>我们沿着光，慢慢走远</p><p class="dim">让时间，再慢一点</p></div>`}</div>${air?`<div class="airplay-panel"><h3>${ic('airplay')} 音乐由发送设备控制</h3><p>曲目切换与进度跳转不可用。<br>按 X 查看接收状态，或断开当前投送。</p></div>`:''}<div class="full-controls">${btn('player-like','like',ic('heart'),'icon-btn','player',`aria-label="喜欢歌曲" ${air?'disabled':''} style="${liked?'color:#ff7e89':''}"`)}${playbackControls(true)}${btn('player-options','more',ic('more'),'icon-btn','player','aria-label="播放选项"')}${output()}</div>${footer(true)}</div>`}
function stateContent(){if(state==='loading')return head('正在寻找好声音','内容加载中，播放控制仍可使用。')+'<div class="skeleton">'+Array(4).fill('<div></div>').join('')+'</div><p class="muted" style="margin-top:24px;font-size:16px">正在连接网易云音乐…</p>';if(state==='empty')return head(titles[scene],'你的下一首喜欢，正在路上。')+`<div class="empty-state"><div class="empty-visual">${ic('library')}</div><h2>${scene==='queue'?'队列还是空的':'这里等待你的第一首歌'}</h2><p>从发现音乐开始，或登录查看你的收藏。</p>${btn('empty-discover','goto:discover','去发现音乐','pill primary')}${btn('empty-account','goto:account','登录账号','pill')}</div>`;if(state==='error')return head(titles[scene],'连接暂时中断，当前音频状态保持不变。')+`<div class="empty-state"><div class="empty-visual">${ic('alert')}</div><h2>暂时无法加载音乐</h2><p>请检查网络后重试，也可以先返回上一页。</p>${btn('retry','retry',ic('refresh')+'重新加载','pill primary')}${btn('error-back','back','返回','pill')}</div>`;return null}
function render(target){const prev=focusId;app.className=reduced?'reduced':'';app.innerHTML=scene==='player'?player():sidebar()+`<section class="content">${stateContent()||({discover,collection,search,library,charts,queue,account,settings}[scene]||discover)()}</section>`+mini()+footer();document.getElementById('scene').value=scene;document.getElementById('state').value=state;app.querySelectorAll('[data-action]').forEach(el=>{el.addEventListener('click',()=>{setFocus(el.dataset.id);act(el.dataset.action)});el.addEventListener('focus',()=>setFocus(el.dataset.id));});const input=document.getElementById('search-query');if(input){input.addEventListener('click',e=>e.stopPropagation());input.addEventListener('keydown',e=>{if(e.key==='Enter'){query=input.value;render('search-input');input.blur();}else if(e.key==='Escape'){e.stopPropagation();input.blur();setFocus('search-input');}});}const initial=scene==='discover'?'card-0':scene==='collection'?'track-0':scene==='player'?'':scene==='settings'?'setting-0':scene==='account'?'qr-refresh':scene==='search'?'search-input':scene==='queue'?'track-'+currentSong:'card-0';setFocus(target||remembered[scene]||initial||prev);if(scene==='player'){app.querySelectorAll('.focused').forEach(x=>x.classList.remove('focused'));focusId='';if(state==='airplay'){app.querySelector('[data-id="previous"]').disabled=true;app.querySelector('[data-id="next"]').disabled=true;app.querySelector('.progress-info').innerHTML='<div class="muted" style="font-size:15px">实时音频 · 进度由发送设备控制</div>';}}}
function setFocus(id){if(scene==='player'&&!modal)return;const els=focusables();const el=els.find(e=>e.dataset.id===id)||els.find(e=>e.dataset.group!=='nav')||els[0];if(!el)return;app.querySelectorAll('.focused').forEach(x=>x.classList.remove('focused'));el.classList.add('focused');if(el.closest('.compact-grid'))el.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'});focusId=el.dataset.id;if(!modal){remembered[scene]=focusId;if(el.dataset.group!=='nav')lastContentFocus[scene]=focusId;}}
function focusables(){return [...app.querySelectorAll((modal?'.modal ':'')+'.focusable')].filter(e=>!e.disabled)}
function go(to){if(to===scene)return;if(scene!=='player')remembered[scene]=focusId;if(to==='player')origin=scene;if(to==='collection')history.push(scene);scene=to;activeTab=0;state='normal';modal=null;modalStack=[];render();}
function back(){if(modal){closeModal();return;}if(scene==='player'){scene=origin;render();return;}if(scene==='collection'){scene=history.pop()||'discover';render();return;}const active=app.querySelector(`[data-id="${focusId}"]`);if(active?.dataset.group==='nav'){setFocus(lastContentFocus[scene]);}else{setFocus('nav-'+scene);}}
function notify(text){clearTimeout(toastTimer);app.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=text;app.appendChild(e);toastTimer=setTimeout(()=>e.remove(),2300)}
function openModal(title,description,options,restoring=false){if(modal&&!restoring)modalStack.push({...modal,focusId});app.querySelector('.modal-layer')?.remove();modal={returnId:focusId,title,description,options};let layer=document.createElement('div');layer.className='modal-layer';layer.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${title}</h2><p>${description}</p><div class="modal-options">${options.map((o,i)=>btn('modal-'+i,o[1],o[0],'','modal')).join('')}</div><div class="modal-footer">${hint('A','选择')}${hint('B','返回')}</div></section>`;app.appendChild(layer);layer.querySelectorAll('[data-action]').forEach(e=>e.onclick=()=>act(e.dataset.action));setFocus('modal-0');}
function closeModal(){const id=modal?.returnId;modal=null;app.querySelector('.modal-layer')?.remove();if(modalStack.length){const parent=modalStack.pop();openModal(parent.title,parent.description,parent.options,true);modal.returnId=parent.returnId;setFocus(parent.focusId);return;}setFocus(id);if(scene==='player')app.querySelectorAll('.focused').forEach(e=>e.classList.remove('focused'));}
function more(){if(scene==='player'||scene==='queue'){if(state==='airplay'){act('airplay-options');return;}openModal('播放选项','按 B 返回，音乐继续播放。',[['喜欢 / 取消喜欢','like'],['随机播放','shuffle'],['循环模式','repeat'],['查看播放队列','goto:queue'],['停止播放','stop']]);}else if(scene==='discover')openModal('发现更多','选择想听的音乐分类。',[['热门歌单','category:热门歌单'],['精品歌单','category:精品歌单'],['每日推荐','daily'],['私人 FM','fm'],['新碟上架','albums'],['电子 / 轻音乐 / ACG / 游戏','category:音乐分类']]);else if(scene==='collection')openModal('收藏与播放','操作当前歌单或选中的歌曲。',[['收藏 / 取消收藏歌单','subscribe'],['喜欢 / 取消喜欢歌曲','like'],['心动模式','intelligence'],['刷新','retry']]);else if(scene==='library')openModal('我的音乐','切换资料库分类。',['我的歌单','我喜欢的音乐','收藏专辑','订阅电台','音乐云盘'].map((t,i)=>[t,'tab:'+i]));else if(scene==='search')openModal('搜索与操作','输入关键词或切换结果类型。',[['输入关键词','search-input'],...['单曲','歌单','专辑','歌手','歌词'].map((t,i)=>[t,'tab:'+i])]);else if(scene==='account')act('account-manage');else if(scene==='settings'){const row=document.querySelector(`[data-id="${focusId}"]`);if(row?.dataset.group!=='nav')act(row.dataset.action);}else notify('已刷新榜单 · 设计演示');}
function act(action){const [name,arg]=action.split(':');if(name==='goto'){if(modal)closeModal();go(arg);return;}switch(name){case 'collection':selectedCollection=Number(arg);go('collection');break;case 'back':back();break;case 'pause':paused=!paused;render(focusId);notify(paused?'已暂停':'继续播放');break;case 'previous':case 'next':if(state==='airplay'){notify('曲目由 AirPlay 发送设备控制');return;}currentSong=(currentSong+(name==='next'?1:songs.length-1))%songs.length;position=0;render(focusId);notify(songs[currentSong][0]);break;case 'track':currentSong=Number(arg);position=0;paused=false;render(focusId);notify('正在播放 · '+songs[currentSong][0]);break;case 'like':liked=!liked;if(modal)closeModal();render(focusId);notify(liked?'已添加到我喜欢的音乐':'已取消喜欢');break;case 'more':more();break;case 'tab':activeTab=Number(arg);if(modal)closeModal();render('tab-'+arg);break;case 'daily':case 'fm':case 'albums':if(modal)closeModal();selectedCollection=0;go('collection');notify(name==='daily'?'每日推荐 · 示例内容':name==='fm'?'私人 FM · 示例内容':'新碟上架 · 示例内容');break;case 'search-input':if(modal)closeModal();document.getElementById('search-query')?.focus();notify('原生应用中打开 Switch 系统键盘');break;case 'retry':state='normal';if(modal)closeModal();render();notify('重新加载完成 · 设计演示');break;case 'account-manage':openModal('账号管理','账号仅为设计示例，不读取本机登录信息。',[['添加账号','qr-refresh'],['示例账号 · CloudTune','account-choice'],['取消','close']]);break;case 'account-choice':openModal('示例账号','切换账号会清空原账号的队列与资料库。',[['取消','close'],['切换到此账号','demo-switch'],['从本机移除','remove-account']]);break;case 'remove-account':openModal('从本机移除账号？','只移除本地会话，不注销网易云音乐账号。',[['取消','close'],['确认移除','demo-remove']]);break;case 'quality':openModal('播放音质','音质由账号与曲目权益决定；高品质选项不代表原格式直通。',[['标准 · 128 kbps','quality-choice:标准'],['较高 · 192 kbps','quality-choice:较高'],['极高 · 320 kbps','quality-choice:极高'],['无损 · FLAC','quality-choice:无损'],['Hi-Res / 环绕 / 母带','quality-more']]);break;case 'quality-more':openModal('更多音质','实际可用性取决于账号权益。',[['Hi-Res · FLAC','quality-choice:Hi-Res'],['高清环绕','quality-choice:高清环绕'],['沉浸环绕','quality-choice:沉浸环绕'],['超清母带','quality-choice:超清母带']]);break;case 'quality-choice':closeModal();notify('音质选择：'+arg+' · 设计演示');break;case 'proxy':openModal('网络代理','原生实现复用 Borealis 系统输入框；留空表示直连。',[['保持直连','close'],['编辑 HTTP / SOCKS5 地址','proxy-edit']]);break;case 'proxy-edit':closeModal();notify('系统键盘输入代理地址 · 此原型不写入配置');break;case 'airplay-options':openModal('AirPlay 1 接收','CloudTune NX · 等待连接 / 已连接 / 播放中。设备名和 IP 由现有服务提供。',[['查看接收界面','airplay-show'],['断开当前投送','disconnect'],['关闭接收','airplay-off'],['返回','close']]);break;case 'airplay-show':closeModal();origin=scene;scene='player';state='airplay';render();break;case 'disconnect':openModal('断开当前投送？','原网易云曲目保留在暂停位置，需要手动恢复。',[['取消','close'],['断开连接','disconnect-confirm']]);break;case 'disconnect-confirm':case 'airplay-off':closeModal();state='normal';paused=true;render();notify('投送已结束 · 原曲保留在暂停位置');break;case 'stop':openModal('停止播放？','停止当前音频并清空当前音频状态。',[['取消','close'],['停止播放','stop-confirm']]);break;case 'stop-confirm':closeModal();paused=true;position=0;render();notify('已停止 · 设计演示');break;case 'exit':openModal('退出 CloudTune NX？','当前为后台服务模式，退出后音乐继续播放。前台模式需提示退出会停止播放。',[['继续听歌','close'],['退出应用','exit-demo']]);break;case 'exit-demo':closeModal();notify('已演示退出确认，设计稿保持打开');break;case 'qr-refresh':if(modal)closeModal();notify('二维码已刷新 · 当前为不可扫码的设计占位');break;case 'subscribe':if(modal)closeModal();notify('收藏状态已切换 · 设计演示');break;case 'shuffle':closeModal();notify('随机播放已开启 · 设计演示');break;case 'repeat':openModal('循环模式','选择播放队列的循环方式。',[['顺序播放','repeat-choice:顺序播放'],['列表循环','repeat-choice:列表循环'],['单曲循环','repeat-choice:单曲循环']]);break;case 'repeat-choice':closeModal();notify(arg+' · 设计演示');break;case 'intelligence':closeModal();notify('心动模式 · 设计演示');break;case 'category':closeModal();notify(arg+' · 设计演示');break;case 'demo-switch':case 'demo-remove':closeModal();notify(name==='demo-switch'?'已演示账号切换，不修改任何账号':'已演示本机移除，不修改任何账号');break;case 'close':closeModal();}}
function move(dir){if(scene==='player'&&!modal){if(dir==='left'||dir==='right'){if(state==='airplay'){notify('AirPlay 进度由发送设备控制');return;}position=Math.max(0,Math.min(272,position+(dir==='right'?10:-10)));render();notify((dir==='right'?'快进':'快退')+' 10 秒');}else adjustVolume(dir==='up'?5:-5);return;}const els=focusables();const from=els.find(e=>e.dataset.id===focusId)||els[0];if(!from)return;const r=from.getBoundingClientRect(),cx=r.x+r.width/2,cy=r.y+r.height/2;let candidates=els.filter(e=>e!==from).map(e=>{let b=e.getBoundingClientRect();return {e,dx:b.x+b.width/2-cx,dy:b.y+b.height/2-cy};}).filter(c=>dir==='left'?c.dx<-4:dir==='right'?c.dx>4:dir==='up'?c.dy<-4:c.dy>4);if(from.dataset.group==='nav'&&(dir==='up'||dir==='down'))candidates=candidates.filter(c=>c.e.dataset.group==='nav');if(from.dataset.group!=='nav'&&(dir==='up'||dir==='down'))candidates=candidates.filter(c=>c.e.dataset.group!=='nav');candidates.forEach(c=>c.score=(dir==='up'||dir==='down')?Math.abs(c.dy)+Math.abs(c.dx)*3:Math.abs(c.dx)+Math.abs(c.dy)*4);candidates.sort((a,b)=>a.score-b.score);if(candidates[0])setFocus(candidates[0].e.dataset.id);}
function adjustVolume(d){volume=Math.max(0,Math.min(100,volume+d));render(focusId);notify('音量 '+volume+'%')}
function command(k){if(k==='back'){back();return;}if(k==='activate'){if(scene==='player'&&!modal){act('pause');return;}const e=focusables().find(e=>e.dataset.id===focusId);if(e){e.animate?.([{filter:'brightness(1)'},{filter:'brightness(1.3)'},{filter:'brightness(1)'}],{duration:reduced?0:110});act(e.dataset.action);}return;}if(['left','right','up','down'].includes(k)){move(k);return;}if(modal)return;if(k==='pause')act('pause');if(k==='more')more();if(k==='player'){if(scene==='player')back();else go('player');}if(k==='previous'||k==='next')act(k);if(k==='voldown'||k==='volup')adjustVolume(k==='volup'?5:-5);if(k==='exit')act('exit');}
document.addEventListener('keydown',e=>{if(e.target.closest('.reviewbar'))return;if(e.target.tagName==='INPUT')return;const m={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',Enter:'activate',a:'activate',A:'activate',Escape:'back',b:'back',B:'back',x:'more',X:'more',y:'pause',Y:'pause',' ':'pause',p:'player',P:'player','+':'player','=':'player',l:'previous',L:'previous',r:'next',R:'next',q:'voldown',Q:'voldown',e:'volup',E:'volup','-':'exit'};if(m[e.key]){e.preventDefault();if(e.repeat&&!['left','right','up','down','volup','voldown'].includes(m[e.key]))return;command(m[e.key]);}else if(e.key==='Tab'&&!e.target.closest('.reviewbar')){e.preventDefault();let els=focusables();let i=els.findIndex(x=>x.dataset.id===focusId);setFocus(els[(i+(e.shiftKey?-1:1)+els.length)%els.length]?.dataset.id);}});
document.getElementById('scene').onchange=e=>{modal=null;go(e.target.value)};document.getElementById('state').onchange=e=>{state=e.target.value;if(state==='airplay'&&scene!=='player'){origin=scene;scene='player';}modal=null;modalStack=[];render();};
document.getElementById('motion').onclick=e=>{reduced=!reduced;e.target.textContent='减少动态：'+(reduced?'开':'关');e.target.setAttribute('aria-pressed',String(reduced));render(focusId)};
function resize(){let clean=document.body.classList.contains('clean');let availableW=clean?innerWidth:innerWidth-56;let availableH=clean?innerHeight:innerHeight-document.querySelector('.reviewbar').offsetHeight-document.querySelector('.reviewfoot').offsetHeight-44;let desired=Number(document.getElementById('resolution').value);let scale=Math.min(availableW/1280,availableH/720,desired/1280);scale=Math.max(.2,scale);app.style.transform=`scale(${scale})`;let v=document.getElementById('viewport');v.style.width=(1280*scale)+'px';v.style.height=(720*scale)+'px';}
document.getElementById('resolution').onchange=resize;document.getElementById('fullscreen').onclick=async()=>{document.body.classList.toggle('clean');try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{}resize();};window.addEventListener('resize',resize);
let gpHeld={},lastAxisAt=0;function pollPad(ts){const gp=[...navigator.getGamepads()].find(Boolean);if(gp){document.getElementById('pad-status').textContent='手柄已连接 · Nintendo 按键位置';const mapping={0:'back',1:'activate',2:'pause',3:'more',4:'previous',5:'next',6:'voldown',7:'volup',8:'exit',9:'player',12:'up',13:'down',14:'left',15:'right'};gp.buttons.forEach((b,i)=>{if(b.pressed&&mapping[i]){if(!gpHeld[i]||(ts-gpHeld[i].first>320&&ts-gpHeld[i].last>120&&[6,7,12,13,14,15].includes(i))){command(mapping[i]);gpHeld[i]={first:gpHeld[i]?.first||ts,last:ts};}}else delete gpHeld[i];});if(ts-lastAxisAt>180){const x=gp.axes[0],y=gp.axes[1];if(Math.abs(x)>.55||Math.abs(y)>.55){command(Math.abs(x)>Math.abs(y)?x>0?'right':'left':y>0?'down':'up');lastAxisAt=ts;}}}requestAnimationFrame(pollPad)}
if(params.get('resolution'))document.getElementById('resolution').value=params.get('resolution');render();resize();requestAnimationFrame(pollPad);
window.designPreview={go,command,act,setState:s=>{state=s;render()},getState:()=>({scene,state,focusId,paused,volume,position,modal:!!modal}),setFocus};
